args:
() => { this.isConnecting = false let headerText = `PUT ${mountPath} HTTP/1.1
` + `Host: ${config.host}:${config.port}
` + `Authorization: Basic ${auth}
` + `Content-Type: audio/ogg; codecs=opus
` + `Ice-Name: FreeShow Audio Stream
` + `Ice-Description: Live Audio Stream from FreeShow
` + `Ice-Genre: Live
` + `Ice-Public: 0
` + `Expect: 100-continue
` + `User-Agent: FreeShow/1.0
` if (this.currentSongTitle) { headerText += `Ice-Title: ${this.currentSongTitle}
` }
